// addGoal manually adds a target : and drops it into the library. ( hangs to the task root. spawns downloads )→ records a message ”New target added” to trigger wake-up.
// planner → The resurrection task , allows the planner to re-judge whether it has been achieved based on the new goal.

func (s *Server) addGoal(w http.ResponseWriter, r *http.Request) {
	t, ok := s.m.Task(r.PathValue("id"))
	if !ok {
		writeErr(w, 404, "task not found")
		return
	}
	if !s.engine.beginTaskOperation(t.ID) {
		writeErr(w, 409, "Task is being deleted,Unable to add target")
		return
	}
	defer s.engine.decInflight(t.ID)

	var body struct {
		Text      string `json:"text"`
		VulnClass string `json:"vulnclass"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeErr(w, 400, "invalid JSON")
		return
	}
	text := strings.TrimSpace(body.Text)
	if text == "" {
		writeErr(w, 400, "Target content cannot be empty")
		return
	}
	payload := map[string]any{"text": text}
	if vc := strings.TrimSpace(body.VulnClass); vc != "" {
		payload["vulnclass"] = vc
	}
	id, err := t.Store.AddGoal(payload, "human")
	if err != nil {
		writeErr(w, 500, err.Error())
		return
	}
	if of, _ := t.Store.OriginFactID(); of > 0 && id > 0 {
		_ = t.Store.Link(of, db.RelSpawns, id) // goal descends from the task root (origin fact)
	}
	t.NotifyGoal([]string{text}) // Note ”People added target :...” trigger and wake up planner
	s.reviveTask(t)              // Bring the completed / suspended task back to the running state and continue running
	node, _ := t.Store.GetNode(id)
	if node == nil {
		writeErr(w, 500, "Read failed after target write")
		return
	}
	writeJSON(w, 200, goalDTO(node))
}

// editGoal manually modified a target text ( and vulnclass): to change the database → record ”The user modified the target from old to new”
// Trigger wake-up planner → Resurrection task , allows planners to adjust direction according to new goals.

func (s *Server) editGoal(w http.ResponseWriter, r *http.Request) {
	t, ok := s.m.Task(r.PathValue("id"))
	if !ok {
		writeErr(w, 404, "task not found")
		return
	}
	if !s.engine.beginTaskOperation(t.ID) {
		writeErr(w, 409, "Task is being deleted,Cannot modify target")
		return
	}
	defer s.engine.decInflight(t.ID)

	gid, err := strconv.ParseInt(r.PathValue("gid"), 10, 64)
	if err != nil || gid <= 0 {
		writeErr(w, 400, "bad goal id")
		return
	}
	var body struct {
		Text      string `json:"text"`
		VulnClass string `json:"vulnclass"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeErr(w, 400, "invalid JSON")
		return
	}
	text := strings.TrimSpace(body.Text)
	if text == "" {
		writeErr(w, 400, "Target content cannot be empty")
		return
	}
	node, err := t.Store.GetNode(gid)
	if err != nil {
		writeErr(w, 500, err.Error())
		return
	}
	if node == nil || node.Kind != db.KindGoal {
		writeErr(w, 404, "Target does not exist")
		return
	}
	oldText := goalDTO(node).Text
	if err := t.Store.UpdateGoalPayload(gid, text, strings.TrimSpace(body.VulnClass)); err != nil {
		writeErr(w, 500, err.Error())
		return
	}
	t.NotifyGoalEdited(oldText, text) // Note ”The person changed the target from old to new” to trigger and wake up planner
	s.reviveTask(t)                   // Consistent with the newly added : resurrection mission, the mission will be re-judged based on the new target.
	updated, _ := t.Store.GetNode(gid)
	if updated == nil {
		writeErr(w, 500, "Read fails after target update")
		return
	}
	writeJSON(w, 200, goalDTO(updated))
}

// deleteGoal Manually delete a target ( Hard deletion , Cascade edge deletion / Anchor point ): Deletion of database → Note ”The user deleted the target X”
// Trigger wake-up planner and re-judge the remaining targets accordingly. According to the product decision ,, delete the [not] resurrection task.

func (s *Server) deleteGoal(w http.ResponseWriter, r *http.Request) {
	t, ok := s.m.Task(r.PathValue("id"))
	if !ok {
