func (s *Server) getFindingTrafficDetail(w http.ResponseWriter, r *http.Request) {
	id, ok := s.findingTrafficAccess(w, r, false)
	if !ok {
		return
	}
	bid, err := strconv.ParseInt(r.PathValue("binding_id"), 10, 64)
	if err != nil || bid <= 0 {
		writeErr(w, 400, "invalid binding id")
		return
	}
	store := s.evidenceStore()
	var result any
	err = store.WithBinding(r.Context(), id, bid, func(b db.FindingTrafficBinding) error {
		req, err := readEvidencePreview(store, b.Snapshot, "request", 0, 8192)
		if err != nil {
			return err
		}
		resp, err := readEvidencePreview(store, b.Snapshot, "response", 0, 8192)
		if err != nil {
			return err
		}
		result = map[string]any{"binding": b, "request": req, "response": resp}
		return nil
	})
	if err != nil {
		evidenceError(w, err)
		return
	}
	writeJSON(w, 200, result)
}

func (s *Server) getFindingTrafficBody(w http.ResponseWriter, r *http.Request) {
	id, ok := s.findingTrafficAccess(w, r, false)
	if !ok {
		return
	}
	bid, err := strconv.ParseInt(r.PathValue("binding_id"), 10, 64)
	if err != nil || bid <= 0 {
		writeErr(w, 400, "invalid binding id")
		return
	}
	side := r.URL.Query().Get("side")
	store := s.evidenceStore()
	// Resolve the binding under the evidence lock, then read the blob without it:
	// both paths below are O(body size) and would otherwise stall every evidence
	// write for as long as the client takes to receive the data.
	b, err := store.Binding(r.Context(), id, bid)
	if err != nil {
		evidenceError(w, err)
		return
	}
	if r.URL.Query().Get("download") == "1" {
		f, length, err := store.OpenBody(b.Snapshot, side)
		if err != nil {
			evidenceError(w, err)
			return
		}
		defer f.Close()
		w.Header().Set("Content-Type", "application/octet-stream")
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=\"evidence-%d-%s.bin\"", bid, side))
		w.Header().Set("Content-Length", strconv.FormatInt(length, 10))
		_, _ = io.Copy(w, f)
		return
	}
	offset, length := int64(0), int64(8192)
	for name, dst := range map[string]*int64{"offset": &offset, "length": &length} {
		if raw := r.URL.Query().Get(name); raw != "" {
			v, err := strconv.ParseInt(raw, 10, 64)
			if err != nil {
				evidenceError(w, err)
				return
			}
			*dst = v
		}
	}
	preview, err := readEvidencePreview(store, b.Snapshot, side, offset, length)
	if err != nil {
		evidenceError(w, err)
		return
	}
	writeJSON(w, 200, preview)
}

func (s *Server) handleSideQuestions(w http.ResponseWriter, r *http.Request, p sidequestion.Parent) {
	key := p.Key()
	if r.Method == "DELETE" {
		s.side.commands.Lock()
		defer s.side.commands.Unlock()
		s.side.mu.Lock()
		for _, run := range s.side.runs {
			if run.key == key {
				run.cancel()
			}
		}
		s.side.mu.Unlock()
		if err := s.m.pg.ClearSideHistory(r.Context(), key); err != nil {
			writeErr(w, 500, err.Error())
			return
		}
		writeJSON(w, 200, map[string]bool{"cleared": true})
		return
	}
	snap, err := s.sideSnapshot(r.Context(), p)
	if err != nil {
		writeErr(w, 500, err.Error())
		return
	}
	if r.Method == "GET" {
		before, _ := strconv.ParseInt(r.URL.Query().Get("before"), 10, 64)
		items, err := s.m.pg.SideHistory(r.Context(), key, before, 21)
		if err != nil {
			writeErr(w, 500, err.Error())
			return
		}
		var next int64
		if len(items) > 20 {
			items = items[:20]
			next = items[len(items)-1].Ordinal
		}
		current, err := s.m.pg.CurrentSideRequest(r.Context(), key)
		if err != nil {
			writeErr(w, 500, err.Error())
			return
		}
		var meta any
		if snap != nil {
			_, modelErr := s.sideProvider(snap.Model)
			reason := ""
			if modelErr != nil {
				reason = modelErr.Error()
			}
			meta = map[string]any{"captured_at": snap.CapturedAt, "model": snap.Model, "available": modelErr == nil, "reason": reason}
		}
		writeJSON(w, 200, map[string]any{"items": items, "current": current, "next_cursor": next, "snapshot": meta})
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, 32<<10)
	var in struct {
		Question string `json:"question"`
		ClientID string `json:"client_request_id"`
	}
	if json.NewDecoder(r.Body).Decode(&in) != nil {
		writeErr(w, 400, "bad json")
		return
	}
	in.Question = strings.TrimSpace(in.Question)
	if in.Question == "" || len([]rune(in.Question)) > 4000 || !validWorkerMessageRequestID(in.ClientID) {
		writeErr(w, 400, "The question must be 1–4000 character，and provide a valid request ID")
		return
	}
	s.side.commands.Lock()
	defer s.side.commands.Unlock()
	if p.TaskID > 0 && s.engine.IsDeleting(strconv.FormatInt(p.TaskID, 10)) {
		writeErr(w, 409, "Task is being archived or deleted")
		return
	}
	if existing, err := s.m.pg.ExistingSideRequest(r.Context(), key, in.ClientID); err != nil {
		writeErr(w, 500, err.Error())
		return
	} else if existing != nil {
		if existing.Question != in.Question {
			writeErr(w, 409, "same request ID Cannot be used for different problems")
			return
		}
		writeJSON(w, 200, existing)
		return
	}
	if snap == nil {
		writeErr(w, 409, "No contextual snapshot yet，Please run the main Agent")
		return
	}
	provider, err := s.sideProvider(snap.Model)
	if err != nil {
		writeErr(w, 409, err.Error())
		return
	}
	s.side.mu.Lock()
	full := len(s.side.runs) >= 4
	busy := false
	for _, run := range s.side.runs {
		if run.key == key {
			busy = true
		}
	}
	s.side.mu.Unlock()
	if busy {
		writeErr(w, 409, db.ErrSideBusy.Error())
		return
	}
	if full {
		writeErr(w, 429, "The bypass request has reached the concurrency limit，Please try again later")
		return
	}
	agentQuestion, ok := s.prepareChatMentionMessage(w, in.Question)
	if !ok {
		return
	}
	if err = s.m.pg.SaveSideSnapshot(r.Context(), *snap); err != nil {
		writeErr(w, 500, err.Error())
		return
	}
	e, created, err := s.m.pg.StartSideRequest(r.Context(), *snap, in.ClientID, in.Question)
	if err != nil {
		writeErr(w, 409, err.Error())
		return
	}
	if created {
		ctx, cancel := context.WithTimeout(s.ctx, 120*time.Second)
		s.side.mu.Lock()
		s.side.runs[e.ID] = sideRun{key: key, parent: p, cancel: cancel, done: make(chan struct{})}
		s.side.mu.Unlock()
		go s.runSide(ctx, cancel, *e, p, provider, *snap, agentQuestion)
	}
	writeJSON(w, 202, e)
}

